UNITS = [
 # (id, Bereich, Art, Titel, Teile, Zusammenfassung)
 ("TU-1JN-001-001-010", "1JN.1.1-1JN.1.10", "section", "Das Wort des Lebens und das Licht",
  ["TU-1JN-001-001-004", "TU-1JN-001-005-010"],
  "Der Brief beginnt ohne Absender mit einem Zeugnis: Das Leben, das beim Vater war, ist erschienen und wurde gehört, gesehen und betastet; die Verkündigung soll Gemeinschaft stiften. Dann die Botschaft: Gott ist Licht. Wer Gemeinschaft mit ihm beansprucht und im Dunkeln lebt, lügt; wer die eigene Sünde leugnet, betrügt sich. Wer bekennt, findet Vergebung."),
 ("TU-1JN-001-001-004", "1JN.1.1-1JN.1.4", "section", "Was wir gesehen und gehört haben", None,
  "Die Zeugen berichten vom «Wort des Lebens», das sie mit allen Sinnen erfahren haben, damit auch die Leser Gemeinschaft mit ihnen und mit dem Vater und dem Sohn haben."),
 ("TU-1JN-001-005-010", "1JN.1.5-1JN.1.10", "section", "Gott ist Licht", None,
  "Drei «Wenn wir sagen» entlarven Selbsttäuschungen: Gemeinschaft mit Gott ohne Leben im Licht, Sündlosigkeit, nie gesündigt zu haben. Das Blut Jesu reinigt; Gott vergibt, wenn wir unsere Sünden bekennen."),
 ("TU-1JN-002-001-029", "1JN.2.1-1JN.2.29", "section", "Gebot, Welt und Antichristen",
  ["TU-1JN-002-001-006", "TU-1JN-002-007-011", "TU-1JN-002-012-017", "TU-1JN-002-018-027", "TU-1JN-002-028-029"],
  "Jesus ist Fürsprecher und Sühne. Gott erkennen heisst seine Gebote halten, vor allem die Liebe zum Bruder. Die Gemeinde wird ermutigt und gewarnt, die Welt nicht zu lieben. Die Abspaltung von «Antichristen», die leugnen, dass Jesus der Christus ist, deutet der Brief als Zeichen der letzten Stunde; die Gemeinde hat die Salbung und soll in dem bleiben, was sie von Anfang an gehört hat."),
 ("TU-1JN-002-001-006", "1JN.2.1-1JN.2.6", "section", "Der Fürsprecher und die Gebote", None,
  "Der Verfasser schreibt, damit sie nicht sündigen; wer doch sündigt, hat in Jesus einen Fürsprecher und die Sühne für die ganze Welt. Wer sagt, er kenne Gott, muss seine Gebote halten und leben wie Jesus."),
 ("TU-1JN-002-007-011", "1JN.2.7-1JN.2.11", "section", "Das alte und neue Gebot", None,
  "Das Gebot ist alt und zugleich neu, weil das wahre Licht schon scheint. Wer seinen Bruder liebt, bleibt im Licht; wer ihn hasst, tappt im Dunkeln."),
 ("TU-1JN-002-012-017", "1JN.2.12-1JN.2.17", "section", "Kinder, Väter, junge Männer", None,
  "In zwei Dreierreihen spricht der Verfasser Kinder, Väter und junge Männer an und bestätigt, was ihnen geschenkt ist. Dann warnt er davor, die Welt mit ihrer Begierde zu lieben; sie vergeht, wer den Willen Gottes tut, bleibt."),
 ("TU-1JN-002-018-027", "1JN.2.18-1JN.2.27", "section", "Antichristen und die Salbung", None,
  "Viele Antichristen sind aufgetreten; sie sind aus der Gemeinde ausgezogen. Der Lügner leugnet, dass Jesus der Christus ist, und damit Vater und Sohn. Die Gemeinde hat die Salbung vom Heiligen, die sie lehrt; sie soll bleiben in dem, was sie von Anfang an gehört hat."),
 ("TU-1JN-002-028-029", "1JN.2.28-1JN.2.29", "section", "Zuversicht bei seinem Kommen", None,
  "Wer in ihm bleibt, kann seinem Kommen mit Zuversicht entgegensehen; wer Gerechtigkeit tut, ist aus ihm geboren."),
 ("TU-1JN-003-001-024", "1JN.3.1-1JN.3.24", "section", "Kinder Gottes",
  ["TU-1JN-003-001-010", "TU-1JN-003-011-018", "TU-1JN-003-019-024"],
  "Gottes Liebe macht die Glaubenden zu seinen Kindern; was sie sein werden, ist noch verborgen. Kinder Gottes und Kinder des Teufels unterscheiden sich am Tun der Gerechtigkeit und an der Liebe. Gegen das Beispiel Kains steht Jesus, der sein Leben hingab; Liebe zeigt sich in Tat und Wahrheit. Wer Gottes Gebote hält, hat Zuversicht vor ihm."),
 ("TU-1JN-003-001-010", "1JN.3.1-1JN.3.10", "section", "Kinder Gottes und die Sünde", None,
  "Die Glaubenden sind jetzt schon Kinder Gottes und werden ihn sehen, wie er ist. Wer aus Gott geboren ist, sündigt nicht; wer die Sünde tut, stammt vom Teufel, dessen Werke der Sohn Gottes zerstören kam."),
 ("TU-1JN-003-011-018", "1JN.3.11-1JN.3.18", "section", "Einander lieben", None,
  "Die Botschaft von Anfang an heisst: einander lieben, nicht wie Kain. Wer hasst, ist ein Mörder. Jesus gab sein Leben hin; ebenso sollen die Glaubenden füreinander einstehen und Not nicht übersehen."),
 ("TU-1JN-003-019-024", "1JN.3.19-1JN.3.24", "section", "Zuversicht vor Gott", None,
  "Auch wenn das Herz verurteilt, ist Gott grösser. Wer seine Gebote hält – an den Namen des Sohnes glauben und einander lieben –, bleibt in ihm; das bezeugt der Geist."),
 ("TU-1JN-004-001-021", "1JN.4.1-1JN.4.21", "section", "Geister prüfen – Gott ist Liebe",
  ["TU-1JN-004-001-006", "TU-1JN-004-007-012", "TU-1JN-004-013-021"],
  "Die Gemeinde soll die Geister prüfen: Aus Gott ist, wer Jesus Christus als im Fleisch gekommen bekennt. Dann der Kern des Briefes: Gott ist Liebe; das zeigt sich darin, dass er seinen Sohn sandte. Wer liebt, bleibt in Gott; Liebe vertreibt die Furcht. Wer Gott liebt, muss auch den Bruder lieben."),
 ("TU-1JN-004-001-006", "1JN.4.1-1JN.4.6", "section", "Die Geister prüfen", None,
  "Viele falsche Propheten sind aufgetreten. Das Bekenntnis zu Jesus Christus, der im Fleisch gekommen ist, unterscheidet den Geist Gottes vom Geist des Antichrists. Die Gemeinde hat die Falschlehrer besiegt, weil der in ihr grösser ist."),
 ("TU-1JN-004-007-012", "1JN.4.7-1JN.4.12", "section", "Gott ist Liebe", None,
  "Die Liebe ist aus Gott; wer nicht liebt, hat Gott nicht erkannt. Gottes Liebe zeigt sich in der Sendung des Sohnes als Sühne. Niemand hat Gott gesehen, aber wo Menschen einander lieben, bleibt er in ihnen."),
 ("TU-1JN-004-013-021", "1JN.4.13-1JN.4.21", "section", "In der Liebe bleiben", None,
  "Der Geist und das Bekenntnis zum Sohn zeigen, dass Gott in den Glaubenden bleibt. Wer in der Liebe bleibt, hat Zuversicht für den Gerichtstag; die vollkommene Liebe treibt die Furcht aus. Wer Gott zu lieben behauptet und den Bruder hasst, lügt."),
 ("TU-1JN-005-001-021", "1JN.5.1-1JN.5.21", "section", "Glaube, Zeugnis und Gewissheit",
  ["TU-1JN-005-001-005", "TU-1JN-005-006-012", "TU-1JN-005-013-021"],
  "Wer glaubt, dass Jesus der Christus ist, ist aus Gott geboren; der Glaube besiegt die Welt. Geist, Wasser und Blut bezeugen den Sohn; wer den Sohn hat, hat das Leben. Der Schluss gibt dem Brief seinen Zweck: Die Leser sollen wissen, dass sie ewiges Leben haben. Er ermutigt zur Fürbitte und schliesst mit der Warnung vor Götzen."),
 ("TU-1JN-005-001-005", "1JN.5.1-1JN.5.5", "section", "Der Glaube besiegt die Welt", None,
  "Glaube an Jesus als den Christus, Liebe zu Gott und zu seinen Kindern und das Halten der Gebote gehören zusammen. Was aus Gott geboren ist, besiegt die Welt."),
 ("TU-1JN-005-006-012", "1JN.5.6-1JN.5.12", "section", "Das Zeugnis über den Sohn", None,
  "Jesus Christus kam durch Wasser und Blut; Geist, Wasser und Blut geben übereinstimmend Zeugnis. Das Zeugnis Gottes lautet: Er hat ewiges Leben gegeben, und dieses Leben ist in seinem Sohn."),
 ("TU-1JN-005-013-021", "1JN.5.13-1JN.5.21", "section", "Gewissheit und Fürbitte", None,
  "Der Verfasser nennt seinen Zweck: Die Glaubenden sollen wissen, dass sie ewiges Leben haben. Gott hört Bitten nach seinem Willen; für Geschwister, die sündigen, soll man bitten. Drei «Wir wissen» fassen zusammen; zuletzt die Mahnung, sich vor Götzen zu hüten."),
 ("TU-2JN-001-001-013", "2JN.1.1-2JN.1.13", "section", "An die auserwählte Herrin",
  ["TU-2JN-001-001-003", "TU-2JN-001-004-006", "TU-2JN-001-007-011", "TU-2JN-001-012-013"],
  "Ein kurzer Brief des «Ältesten» an eine Gemeinde, als «auserwählte Herrin» angesprochen. Er freut sich über ihre Treue, erinnert an das Gebot der gegenseitigen Liebe und warnt vor Verführern, die das Kommen Jesu Christi im Fleisch nicht bekennen: Ihnen soll keine Gastfreundschaft gewährt werden. Mehr will er bei einem Besuch sagen."),
 ("TU-2JN-001-001-003", "2JN.1.1-2JN.1.3", "greeting", "Gruss in Wahrheit und Liebe", None,
  "Der Älteste grüsst die auserwählte Herrin und ihre Kinder, die er in Wahrheit liebt, und wünscht Gnade, Barmherzigkeit und Frieden."),
 ("TU-2JN-001-004-006", "2JN.1.4-2JN.1.6", "section", "In der Wahrheit leben", None,
  "Er freut sich, dass einige ihrer Kinder in der Wahrheit leben, und erinnert an das Gebot von Anfang an: einander lieben und nach Gottes Geboten leben."),
 ("TU-2JN-001-007-011", "2JN.1.7-2JN.1.11", "section", "Warnung vor Verführern", None,
  "Viele Verführer bekennen nicht, dass Jesus Christus im Fleisch kommt. Wer über die Lehre Christi hinausgeht, hat Gott nicht; solche Lehrer soll die Gemeinde nicht aufnehmen."),
 ("TU-2JN-001-012-013", "2JN.1.12-2JN.1.13", "greeting", "Besuch und Grüsse", None,
  "Statt mit Papier und Tinte will der Älteste persönlich reden; es grüssen die Kinder der auserwählten Schwester."),
 ("TU-3JN-001-001-014", "3JN.1.1-3JN.1.14", "section", "An Gaius",
  ["TU-3JN-001-001-004", "TU-3JN-001-005-008", "TU-3JN-001-009-010", "TU-3JN-001-011-012", "TU-3JN-001-013-014"],
  "Ein persönlicher Brief des Ältesten an Gaius. Er lobt dessen Gastfreundschaft für reisende Missionare und bittet, sie weiter zu unterstützen. Diotrephes dagegen weist die Boten ab und schliesst Gastgeber aus der Gemeinde aus. Demetrius wird empfohlen; ein Besuch ist angekündigt."),
 ("TU-3JN-001-001-004", "3JN.1.1-3JN.1.4", "greeting", "Gruss an Gaius", None,
  "Der Älteste grüsst den geliebten Gaius, wünscht ihm Wohlergehen und freut sich über das Zeugnis, dass er in der Wahrheit lebt."),
 ("TU-3JN-001-005-008", "3JN.1.5-3JN.1.8", "section", "Gastfreundschaft für Reisende", None,
  "Gaius hat fremde Geschwister treu aufgenommen. Sie sind um des Namens willen unterwegs und nehmen von Heiden nichts an; deshalb sollen die Gemeinden sie unterstützen und so Mitarbeiter der Wahrheit werden."),
 ("TU-3JN-001-009-010", "3JN.1.9-3JN.1.10", "section", "Diotrephes", None,
  "Diotrephes, der der Erste sein will, erkennt den Ältesten nicht an, redet schlecht über ihn, nimmt die Reisenden nicht auf und schliesst andere, die es tun wollen, aus der Gemeinde aus."),
 ("TU-3JN-001-011-012", "3JN.1.11-3JN.1.12", "section", "Das Gute nachahmen", None,
  "Gaius soll das Gute nachahmen, nicht das Böse. Demetrius hat ein gutes Zeugnis von allen und von der Wahrheit selbst."),
 ("TU-3JN-001-013-014", "3JN.1.13-3JN.1.14", "greeting", "Schluss und Grüsse", None,
  "Der Älteste will bald persönlich kommen; Friedensgruss und Grüsse von Freund zu Freund."),
]
UNITS_GSW = {
 "TU-1JN-001-001-010": ("S Wort vom Läbe und s Liecht", "De Brief fangt ohni Absänder mit eme Zügnis aa: S Läbe, wo bim Vatter gsii isch, isch erschine, und me hät s ghört, gseh und aaglanget; d Verchündigung söll Gmeinschaft schaffe. Dänn d Botschaft: Gott isch Liecht. Wär Gmeinschaft mit ihm beaasprucht und im Dunkle läbt, lüügt; wär di eiget Sünd abstritet, verfüert sich sälber. Wär bekännt, findt Vergäbig."),
 "TU-1JN-001-001-004": ("Was mir gseh und ghört händ", "D Züüge verzelled vom «Wort vom Läbe», wo si mit allne Sinn erläbt händ, demit au d Läser Gmeinschaft mit ine und mit em Vatter und em Sohn händ."),
 "TU-1JN-001-005-010": ("Gott isch Liecht", "Drüü «Wänn mir säged» decked Sälbschttüüschige uuf: Gmeinschaft mit Gott ohni Läbe im Liecht, kei Sünd ha, nie gsündiget ha. S Bluet vo Jesus macht suuber; Gott vergit, wänn mir öisi Sünde bekänned."),
 "TU-1JN-002-001-029": ("Gebot, Wält und Antichrischte", "Jesus isch Fürspräch und Süeni. Gott kenne heisst sini Gebot halte, vor allem d Liebi zum Brueder. D Gmeind wird ermuetiget und gwarnt, d Wält nöd z liebe. D Abspaltig vo «Antichrischte», wo abstriited, dass Jesus de Christus isch, düütet de Brief als Zeiche vo de letschte Stund; d Gmeind hät d Salbig und söll i dem bliibe, wo si vo Aafang aa ghört hät."),
 "TU-1JN-002-001-006": ("De Fürspräch und d Gebot", "De Verfasser schriibt, demit si nöd sündiged; wär glich sündiget, hät in Jesus en Fürspräch und d Süeni für di ganz Wält. Wär seit, er kenni Gott, muess sini Gebot halte und läbe wie Jesus."),
 "TU-1JN-002-007-011": ("S alt und s nöi Gebot", "S Gebot isch alt und gliichziitig nöi, wil s wahr Liecht scho schiint. Wär sin Brueder liebt, bliibt im Liecht; wär en hasst, tappt im Dunkle."),
 "TU-1JN-002-012-017": ("Chind, Vätter, jungi Manne", "I zwei Dreierreihe redt de Verfasser Chind, Vätter und jungi Manne aa und bestätiget, was ine gschänkt isch. Dänn warnt er devor, d Wält mit irer Begierd z liebe; si vergaat, wär de Wille vo Gott tuet, bliibt."),
 "TU-1JN-002-018-027": ("Antichrischte und d Salbig", "Vil Antichrischte sind uftrete; si sind us de Gmeind uszoge. De Lügner stritet ab, dass Jesus de Christus isch, und demit de Vatter und de Sohn. D Gmeind hät d Salbig vom Heilige, wo si lehrt; si söll i dem bliibe, wo si vo Aafang aa ghört hät."),
 "TU-1JN-002-028-029": ("Zueversicht bi sim Cho", "Wär in ihm bliibt, cha sim Cho mit Zueversicht entgägeluege; wär Grächtigkeit tuet, isch us ihm gebore."),
 "TU-1JN-003-001-024": ("Chind vo Gott", "Gottes Liebi macht d Gläubige zu sine Chind; was si sii wärded, isch no verborge. D Chind vo Gott und d Chind vom Tüüfel underscheided sich am Tue vo de Grächtigkeit und a de Liebi. Gäge s Biispiil vom Kain staat Jesus, wo sis Läbe häregää hät; Liebi zeigt sich i Tat und Wahrheit. Wär Gottes Gebot haltet, hät Zueversicht vor ihm."),
 "TU-1JN-003-001-010": ("Chind vo Gott und d Sünd", "D Gläubige sind jetzt scho Chind vo Gott und wärded en gseh, wie er isch. Wär us Gott gebore isch, sündiget nöd; wär d Sünd tuet, chunnt vom Tüüfel, und dem sini Wärch isch de Sohn vo Gott cho zerstöre."),
 "TU-1JN-003-011-018": ("Enand liebe", "D Botschaft vo Aafang aa heisst: enand liebe, nöd wie de Kain. Wär hasst, isch en Mörder. Jesus hät sis Läbe häregää; gliich söled d Gläubige füreinand iistaa und d Not nöd übersee."),
 "TU-1JN-003-019-024": ("Zueversicht vor Gott", "Au wänn s Härz verurteilt, isch Gott grösser. Wär sini Gebot haltet – a de Name vom Sohn glaube und enand liebe –, bliibt in ihm; das bezüüget de Geischt."),
 "TU-1JN-004-001-021": ("Geischter prüefe – Gott isch Liebi", "D Gmeind söll d Geischter prüefe: Us Gott isch, wär bekännt, dass Jesus Christus im Fleisch cho isch. Dänn de Kern vom Brief: Gott isch Liebi; das zeigt sich dra, dass er sin Sohn gschickt hät. Wär liebt, bliibt in Gott; Liebi tribt d Angscht uus. Wär Gott liebt, muess au de Brueder liebe."),
 "TU-1JN-004-001-006": ("D Geischter prüefe", "Vil falschi Prophete sind uftrete. S Bekänntnis zu Jesus Christus, wo im Fleisch cho isch, underscheidet de Geischt vo Gott vom Geischt vom Antichrischt. D Gmeind hät di falsche Lehrer besiegt, wil dä in ere grösser isch."),
 "TU-1JN-004-007-012": ("Gott isch Liebi", "D Liebi isch us Gott; wär nöd liebt, hät Gott nöd erchännt. Gottes Liebi zeigt sich dra, dass er de Sohn als Süeni gschickt hät. Niemer hät Gott gseh, aber wo Mänsche enand liebed, bliibt er in ine."),
 "TU-1JN-004-013-021": ("I de Liebi bliibe", "De Geischt und s Bekänntnis zum Sohn zeiged, dass Gott i de Gläubige bliibt. Wär i de Liebi bliibt, hät Zueversicht für de Tag vom Gricht; di vollkomme Liebi tribt d Angscht uus. Wär seit, er liebi Gott, und de Brueder hasst, lüügt."),
 "TU-1JN-005-001-021": ("Glaube, Zügnis und Gwüssheit", "Wär glaubt, dass Jesus de Christus isch, isch us Gott gebore; de Glaube besiegt d Wält. Geischt, Wasser und Bluet bezüüged de Sohn; wär de Sohn hät, hät s Läbe. De Schluss git em Brief sin Zwäck: D Läser söled wüsse, dass si ewigs Läbe händ. Er ermuetiget zur Fürbitt und hört mit de Warnig vor de Götze uf."),
 "TU-1JN-005-001-005": ("De Glaube besiegt d Wält", "De Glaube a Jesus als de Christus, d Liebi zu Gott und zu sine Chind und s Halte vo de Gebot ghöred zäme. Was us Gott gebore isch, besiegt d Wält."),
 "TU-1JN-005-006-012": ("S Zügnis über de Sohn", "Jesus Christus isch dur Wasser und Bluet cho; Geischt, Wasser und Bluet gänd überiistimmend Zügnis. S Zügnis vo Gott heisst: Er hät ewigs Läbe gää, und das Läbe isch in sim Sohn."),
 "TU-1JN-005-013-021": ("Gwüssheit und Fürbitt", "De Verfasser nännt sin Zwäck: D Gläubige söled wüsse, dass si ewigs Läbe händ. Gott ghört Bitte nach sim Wille; für Gschwüschterti, wo sündiged, söll me bätte. Drüü «Mir wüssed» fassed zäme; zletscht d Mahnig, sich vor de Götze z hüete."),
 "TU-2JN-001-001-013": ("A di uuserwählt Herrin", "En churze Brief vom «Ältischte» a e Gmeind, wo als «uuserwählti Herrin» aagredt wird. Er fröit sich über iri Tröii, erinneret as Gebot vo de gägesiitige Liebi und warnt vor Verfüerer, wo nöd bekänned, dass Jesus Christus im Fleisch chunnt: Dene söll me kei Gaschtfründschaft gää. Meh wott er bi me Bsuech säge."),
 "TU-2JN-001-001-003": ("Gruess i Wahrheit und Liebi", "De Ältischt grüesst di uuserwählt Herrin und iri Chind, wo er i Wahrheit liebt, und wünscht Gnad, Barmhärzigkeit und Fride."),
 "TU-2JN-001-004-006": ("I de Wahrheit läbe", "Er fröit sich, dass es paar vo irne Chind i de Wahrheit läbed, und erinneret as Gebot vo Aafang aa: enand liebe und nach Gottes Gebot läbe."),
 "TU-2JN-001-007-011": ("Warnig vor Verfüerer", "Vil Verfüerer bekänned nöd, dass Jesus Christus im Fleisch chunnt. Wär über d Lehr vo Christus usegaat, hät Gott nöd; settigi Lehrer söll d Gmeind nöd ufnää."),
 "TU-2JN-001-012-013": ("Bsuech und Grüess", "Statt mit Papier und Tinte wott de Ältischt persönlich rede; es grüessed d Chind vo de uuserwählte Schwöschter."),
 "TU-3JN-001-001-014": ("Am Gaius", "En persönliche Brief vom Ältischte am Gaius. Er lobt sini Gaschtfründschaft für reisendi Missionar und bittet en, si wiiter z unterstütze. De Diotrephes dägäge wiist d Bote ab und schlüüsst Gaschtgäber us de Gmeind uus. De Demetrius wird empfohle; en Bsuech isch aagchündet."),
 "TU-3JN-001-001-004": ("Gruess am Gaius", "De Ältischt grüesst de lieb Gaius, wünscht em, dass es em guet gaat, und fröit sich über s Zügnis, dass er i de Wahrheit läbt."),
 "TU-3JN-001-005-008": ("Gaschtfründschaft für Reisendi", "De Gaius hät frömdi Gschwüschterti tröi ufgnoo. Si sind wäge em Name understwägs und nämed vo Heide nüt aa; drum söled d Gmeinde si unterstütze und so Mitarbeiter vo de Wahrheit wärde."),
 "TU-3JN-001-009-010": ("De Diotrephes", "De Diotrephes, wo de Erscht sii wott, anerchännt de Ältischt nöd, redt schlächt über en, nimmt d Reisende nöd uf und schlüüsst anderi, wo s wänd, us de Gmeind uus."),
 "TU-3JN-001-011-012": ("S Guet nachemache", "De Gaius söll s Guet nachemache, nöd s Bös. De Demetrius hät es guets Zügnis vo allne und vo de Wahrheit sälber."),
 "TU-3JN-001-013-014": ("Schluss und Grüess", "De Ältischt wott bald persönlich cho; Fridesgruess und Grüess vo Fründ zu Fründ."),
}

NOTES_DE = ["KI-Entwurf ohne fachliche Prüfung.",
            ("Die Zuordnung von Handschriften zu Lesarten in den Alternativen beruht auf maschineller Kollation "
             "(METHOD-AUTO-COLLATION-V1) bzw. auf der CNTR-Transkription, nicht auf eigener Prüfung der Handschriften. "
             "Wo erfasster Wortlaut und automatische Zuordnung auseinandergehen, ist das in der Alternative vermerkt.")]
NOTES_GSW = ["KI-Entwurf ohni fachlichi Prüefig.", "D Mundart isch no nöd vo ere muettersprachliche Person prüeft.",
             ("D Zueornig vo Handschrifte zu Läsarte beruet uf maschineller Kollation (METHOD-AUTO-COLLATION-V1) oder uf de "
              "CNTR-Transkription, nöd uf eigeter Prüefig vo de Handschrifte. Wo erfasste Wortlut und automatischi Zueornig "
              "usenand gönd, isch das i de Alternative vermerkt.")]
NOTES_EXTRA = {
 ("1JN", 4, "de"): ["Die in der Forschung diskutierte Lesart «der Jesus auflöst» (λύει) in [[1JN.4.3]] ist im importierten Apparat nicht erfasst und deshalb nicht als Alternative geführt."],
 ("1JN", 4, "gsw"): ["Di Läsart «wo de Jesus uflöst» (λύει) i [[1JN.4.3]], wo i de Forschig diskutiert wird, isch im importierte Apparat nöd erfasst und drum nöd als Alternative gfüert."],
 ("1JN", 5, "de"): ["Zum sogenannten Comma Johanneum in [[1JN.5.7]]-[[1JN.5.8]] siehe die Übersetzungsentscheidung zu [[1JN.5.7]]; der importierte Apparat führt dort keine Variante."],
 ("1JN", 5, "gsw"): ["Zum sogenannte Comma Johanneum i [[1JN.5.7]]-[[1JN.5.8]] lueg d Übersetzigsentscheidig zu [[1JN.5.7]]; de importiert Apparat füert dört kei Variante."],
 ("3JN", 1, "de"): ["Verszählung nach KJV: [[3JN.1.14]] umfasst auch den Gruss, den das SBLGNT als eigenen Vers 15 zählt (Tokens 11–21 tragen die ursprüngliche Stellenangabe in source_reference)."],
 ("3JN", 1, "gsw"): ["Verszellig nach KJV: [[3JN.1.14]] umfasst au de Gruess, wo s SBLGNT als eigete Vers 15 zellt (d Tokens 11–21 träged di ursprünglich Stelleaagab in source_reference)."],
}


def run():
    import json
    n = 0
    for book, name, chapters in BOOKS:
        work = f"WORK-{book}"
        n += write(D / "works" / f"{work}.json", {"id": work, "type": "work", "status": "draft", "tags": TAGS,
                                                 "name": name, "original_language": "grc"})
        for uid, rng, kind, title, parts, summary in UNITS:
            if not uid.startswith(f"TU-{book}-"):
                continue
            rec = {"id": uid, "type": "text_unit", "status": "draft", "tags": TAGS, "work": work, "range": rng, "kind": kind,
                   "title": title, **({"parts": parts} if parts else {}),
                   "segmentation_note_de": "Gliederungsvorschlag; die Abgrenzung der Abschnitte ist eine redaktionelle Entscheidung." if parts else None,
                   "knowledge": {"asserted_at": DATE, "supersedes": None}, "summary_de": summary, "summary_authorship_de": AUTH}
            rec = {k: v for k, v in rec.items() if v is not None}
            n += write(D / "text-units" / f"{uid}.json", rec)
            gt, gs = UNITS_GSW[uid]
            n += localize(uid, rec, {"title": gt, "summary_de": gs}, "gsw-u-sd-chzh", "GSW-ZH", "CTX-CH-ZH-GSW-2026", AUTH_GSW_L10N, DATE)
        variants = {}
        for p in (D / "variants" / f"sblgntapp-{book.lower()}").glob("*.json"):
            v = json.loads(p.read_text(encoding="utf-8"))
            variants[v["id"]] = v
        for c, last in chapters:
            ts_id, toks = load_tokens(D / "tokens" / f"SBLGNT-{book}-{c:03d}.json")
            refs_c = [f"{book}.{c}.{v}" for v in range(1, last + 1)]
            if set(refs_c) != set(toks):
                raise SystemExit(f"{book} {c}: Verse {sorted(set(toks) ^ set(refs_c))} passen nicht zu den Tokens")
            follows = sorted(f"{vid}:R1" for vid, v in variants.items() if v["reference"] in refs_c)
            for lang, markup, decs, code in (("de", DE, DEC_DE, "DE"), ("gsw", GSW, DEC_GSW, "GSW-ZH")):
                texts, aligns = {}, []
                for r in refs_c:
                    words = {pos: t["word"] for pos, t in toks[r].items()}
                    text, al = alignment_entries(r, markup[r], words, lambda p, r=r: toks[r][p]["id"])
                    texts[r], aligns = text, aligns + al
                tid = f"TRANS-{book}-{c:03d}-001-{last:03d}-{code}-WORKING"
                dec = [{"reference": r, "target": tg, "kind": kd, "grc": grc, **({"more_literal": ml} if ml else {}),
                        **({"other_options": oo} if oo else {}), "note": nt}
                       for r, tg, kd, grc, ml, oo, nt in decs if r in refs_c]
                for d in dec:
                    if d["target"] not in texts[d["reference"]]:
                        raise SystemExit(f"{tid}: Entscheidung {d['target']!r} nicht im Text {d['reference']}")
                alts = []
                for a in ALTS:
                    vid, ref, f_de, t_de, f_g, t_g, eff, n_de, n_g, w_de, w_g, o_de, o_g = a
                    if ref not in refs_c:
                        continue
                    var = variants.get(vid.split(":")[0])
                    if not var:
                        raise SystemExit(f"{tid}: Variante {vid} nicht im Apparat")
                    ids = {x["reading_id"] for x in var["readings"]}
                    if vid.split(":")[1] not in ids or set(w_de) - ids or set(w_g) - ids:
                        raise SystemExit(f"{tid}: Lesarten von {vid} passen nicht zum Apparat")
                    f_, t_, nt, ws, og = (f_de, t_de, n_de, w_de, o_de) if lang == "de" else (f_g, t_g, n_g, w_g, o_g)
                    if f_ not in texts[ref]:
                        raise SystemExit(f"{tid}: Alternative {f_!r} nicht im Text {ref}")
                    alts.append({"reading": vid, "reference": ref, "from_text": f_, "to_text": t_, "effect": eff, "note": nt,
                                 "readings": {k: [{"grc": g, "text": x, **({"note": h} if h else {})} for g, x, h in v] for k, v in ws.items()},
                                 "origin": og})
                rec = {"id": tid, "type": "translation", "status": "draft", "tags": TAGS, "reference": f"{book}.{c}.1-{book}.{c}.{last}",
                       "language": "de-CH" if lang == "de" else "gsw-u-sd-chzh", "translation_kind": "literal_original_working"}
                if lang == "gsw":
                    rec.update({"language_label_de": "Züridüütsch", "language_name_de": "Zürichdeutsch", "target_context": "CTX-CH-ZH-GSW-2026",
                                "orthography_de": "Dieth-Schreibung (Schwyzertütschi Dialäktschrift, 2. Aufl. 1986), lautnah: lange Vokale doppelt (Broot, Riich), ä für offenes e.",
                                "register_de": "Nah am griechischen Wortlaut, aber so, wie man es sagt: Perfekt statt Präteritum, «wo» als Relativpartikel, kein Genitiv. Jede Abweichung vom Wörtlichen ist in decisions markiert.",
                                "control_translation": f"TRANS-{book}-{c:03d}-001-{last:03d}-DE-WORKING",
                                "review_de": "Mundart noch nicht geprüft. Vorgesehen: Prüfung durch Andi Neck (Muttersprachler), mit Datum einzutragen."})
                rec.update({"method_de": ("Wörtlich orientierte Arbeitsübersetzung aus dem SBLGNT: Satzbau und Wortwahl des Griechischen möglichst sichtbar, verständliches Deutsch. Schweizer Rechtschreibung. Eigene Formulierung; nicht aus einer veröffentlichten deutschen Bibel übernommen."
                                           if lang == "de" else "Direkt aus dem SBLGNT übersetzt, mit Wortzuordnung zu den Token; die hochdeutsche Arbeitsübersetzung dient nur als Kontrolle. Nicht aus einer veröffentlichten Mundart-Bibel übernommen."),
                            "based_on_edition": "ED-SBLGNT", "based_on_tokens": ts_id, "follows_readings": follows,
                            "text_by_reference": texts, "authorship_de": AUTH if lang == "de" else AUTH_GSW,
                            "translation_notes": (NOTES_DE if lang == "de" else NOTES_GSW) + NOTES_EXTRA.get((book, c, lang), []),
                            "knowledge": {"asserted_at": DATE, "supersedes": None}, "decisions": dec,
                            "decisions_note_de": "Übersetzungsentscheidungen: wörtlich (literal), sprachlich angepasst (adapted), Deutungsentscheidung (interpretive) oder der vertrauten Wiedergabe folgend (traditional). " + (AUTH if lang == "de" else AUTH_GSW)})
                if alts:
                    rec["alternatives"] = alts
                    rec["alternatives_note_de"] = "Wiedergabe abweichender Lesarten, soweit sie die Übersetzung verändern. " + (AUTH if lang == "de" else AUTH_GSW)
                    rec["alternatives_origin_note"] = ("Mögliche Erklärungen, wie die Unterschiede entstanden sein könnten. Sie stehen nebeneinander; keine ist als richtig entschieden."
                                                       if lang == "de" else "Möglichi Erkläärige, wie d Underschid entstande sii chönnted. Si stönd näbenand; keini isch als richtig entschide.")
                n += write(D / "translations" / f"{tid}.json", rec)
                aid = f"ALIGN-{book}-{c:03d}-001-{last:03d}-{code}-001"
                n += write(D / "alignments" / f"{aid}.json", {
                    "id": aid, "type": "alignment", "status": "draft", "tags": TAGS, "reference": f"{book}.{c}.1-{book}.{c}.{last}",
                    "source_language": "grc", "target_language": rec["language"], "source_basis": "ED-SBLGNT", "source_tokens_set": ts_id,
                    "target_translation": tid, "coverage": "complete",
                    "coverage_de": f"Jedes der {sum(len(toks[r]) for r in refs_c)} SBLGNT-Tokens ist genau einer Zuordnung zugewiesen.",
                    "target_convention_de": "« … » trennt nicht zusammenhängende Teile des Wortlauts. Text und Zuordnung sind aus derselben Auszeichnung erzeugt (scripts/authoring/johannesbriefe_text.py).",
                    "authorship_de": AUTH if lang == "de" else AUTH_GSW, "knowledge": {"asserted_at": DATE, "supersedes": None},
                    "alignments": aligns})
    print(f"PASS: Johannesbriefe – Texteinheiten, Übersetzungen de/gsw, Wortzuordnung; {n} Dateien geschrieben")


if __name__ == "__main__":
    run()
